def f(grid):
    bg=max({v for row in grid for v in row}, key=lambda v: sum(r.count(v) for r in grid))
    H,W=len(grid),len(grid[0])
    cells=[(r,c) for r in range(H) for c in range(W) if grid[r][c]!=bg]
    rs=[r for r,_ in cells]; cs=[c for _,c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    out=[row[:] for row in grid]
    height,width=r1-r0+1,c1-c0+1
    # a row/col is a line if it is a bbox border, or has >= half of the perpendicular extent filled
    rowline={r: (r in (r0,r1)) or sum(1 for c in range(c0,c1+1) if grid[r][c]!=bg)>=width/2 for r in range(r0,r1+1)}
    colline={c: (c in (c0,c1)) or sum(1 for r in range(r0,r1+1) if grid[r][c]!=bg)>=height/2 for c in range(c0,c1+1)}
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if grid[r][c]==bg and (rowline[r] or colline[c]):
                out[r][c]=2
    return out

