lib='''
def background(grid):
    """The most frequent color in the grid."""
    return max({v for row in grid for v in row}, key=lambda v: sum(r.count(v) for r in grid))

def bbox(grid, bg=None):
    """(r0, r1, c0, c1) bounds of the non-background cells; None if empty."""
    if bg is None: bg = background(grid)
    cells=[(r,c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c]!=bg]
    if not cells: return None
    rs=[r for r,_ in cells]; cs=[c for _,c in cells]
    return min(rs),max(rs),min(cs),max(cs)

def complete_lines(grid, fill=2, frac=0.5):
    """Fill background cells lying on the shape's straight lines (bbox frame plus internal rows/cols at least frac filled) with color fill."""
    bg = background(grid)
    r0,r1,c0,c1 = bbox(grid, bg)
    height,width = r1-r0+1, c1-c0+1
    out=[row[:] for row in grid]
